using Microsoft.Data.SqlClient;
namespace He_Thong_GYM.DAL;
public sealed class ThongKeDAL{public async Task<Dictionary<string,decimal>> LayAsync(){const string q="SELECT N'Thành viên' Ten,COUNT(*) GiaTri FROM dbo.ThanhVien UNION ALL SELECT N'Doanh thu thực',ISNULL(SUM(CASE WHEN LoaiGiaoDich=N'Thanh toán' THEN SoTien ELSE -SoTien END),0) FROM dbo.ThanhToan WHERE TrangThai=N'Thành công' UNION ALL SELECT N'Công nợ',ISNULL(SUM(TongTien-ISNULL(p.DaTra,0)),0) FROM dbo.HoaDon h OUTER APPLY(SELECT SUM(CASE WHEN LoaiGiaoDich=N'Thanh toán' THEN SoTien ELSE -SoTien END) DaTra FROM dbo.ThanhToan WHERE MaHD=h.MaHD AND TrangThai=N'Thành công')p WHERE h.TrangThai<>N'Hủy' UNION ALL SELECT N'Giá trị tồn',ISNULL(SUM(SoLuongTon*GiaNhap),0) FROM dbo.SanPham UNION ALL SELECT N'Chi phí bảo trì',ISNULL(SUM(ChiPhi),0) FROM dbo.BaoTriThietBi;";var k=new Dictionary<string,decimal>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k[r.GetString(0)]=r.GetDecimal(1);return k;}}
